INSERT INTO B_GIFT_POINT( CNTR_YMD ,UPPER_LOCGOV_CODE ,UPPER_LOCGOV_NM ,LOCGOV_CODE ,LOCGOV_NM ,POINT_CAT ,GIFT_CNT ,CNTR_RATE ,FRST_REG_DT ) SELECT TO_CHAR(SYSDATE ,'YYYYMMDD') CNTR_YMD , CLG.UPPER_LOCGOV_CODE , CLG.UPPER_LOCGOV_NM , CLG.LOCGOV_CODE , CLG.LOCGOV_NM , BASE.TXT , NVL(RS.REGCNT,0) AS REGCNT , NVL(RS.RATE,0) AS RATE , DATE_FORMAT(NOW(),'%Y-%M-%D %H:%I:%S') FRST_REG_DT FROM ( SELECT R2.LOCGOV_CODE ,R1.TXT ,R1.ORD FROM ( SELECT '~1.5만' AS TXT , 1 AS ORD FROM DB_ROOT UNION ALL SELECT '1.5만~3만' AS TXT , 2 AS ORD FROM DB_ROOT UNION ALL SELECT '3만' AS TXT , 3 AS ORD FROM DB_ROOT UNION ALL SELECT '3만~6만' AS TXT , 4 AS ORD FROM DB_ROOT UNION ALL SELECT '6만' AS TXT , 5 AS ORD FROM DB_ROOT UNION ALL SELECT '6만~' AS TXT , 6 AS ORD FROM DB_ROOT ) AS R1 CROSS JOIN ( SELECT LOCGOV_CODE FROM G_LOCGOV WHERE USE_AT = 'Y' ) R2 ) BASE LEFT OUTER JOIN ( SELECT T2.LOCGOV_CODE , T2.NAME , T2.REGCNT , FORMAT((T2.REGCNT*1.0) / (SUM(T2.REGCNT)OVER(PARTITION BY T2.LOCGOV_CODE)*1.0) * 100, 1) AS RATE FROM ( SELECT T1.LOCGOV_CODE , T1.NAME , COUNT(T1.ITEM_ID) AS REGCNT FROM (
SELECT OS.LOCGOV_CODE , CASE WHEN OI.SALE_PRICE <= 15000 THEN '~1.5만' WHEN OI.SALE_PRICE > 15000 AND OI.SALE_PRICE < 30000 THEN '1.5만~3만' WHEN OI.SALE_PRICE = 30000 THEN '3만' WHEN OI.SALE_PRICE > 30000 AND OI.SALE_PRICE < 60000 THEN '3만~6만' WHEN OI.SALE_PRICE = 60000 THEN '6만' WHEN OI.SALE_PRICE > 60000 THEN '6만~' ELSE '기타' END AS NAME , OI.ITEM_ID FROM OP_ITEM OI INNER JOIN OP_ITEM_CATEGORY OIC ON OI.ITEM_ID = OIC.ITEM_ID INNER JOIN OP_CATEGORY OC ON OIC.CATEGORY_ID = OC.CATEGORY_ID INNER JOIN OP_CATEGORY_GROUP OCG ON OC.CATEGORY_GROUP_ID = OCG.CATEGORY_GROUP_ID INNER JOIN OP_SELLER OS ON OI.SELLER_ID = OS.SELLER_ID INNER JOIN G_LOCGOV GL ON OS.LOCGOV_CODE = GL.LOCGOV_CODE WHERE 1 = 1 AND OI.DATA_STATUS_CODE IN ('30', '0', '1')
) AS T1 GROUP BY T1.LOCGOV_CODE , T1.NAME ) AS T2 ) AS RS ON RS.LOCGOV_CODE = BASE.LOCGOV_CODE AND RS.NAME = BASE.TXT LEFT JOIN G_LOCGOV CLG ON CLG.LOCGOV_CODE = BASE.LOCGOV_CODE ORDER BY CLG.LOCGOV_CODE , BASE.ORD
